create table veranolink.vl_tokens (
    id_vl_token              number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment
    by 1 cache 20 noorder nocycle nokeep noscale not null enable,
    access_token             varchar2(4000 char),
    token_type               varchar2(10 char),
    primetenant              varchar2(100 char),
    primetenantcode          varchar2(100 char),
    userid                   varchar2(100 char),
    primeidentityapp         varchar2(100 char),
    expirein                 number,
    x_prime_tenant           varchar2(100 char),
    x_prime_identity_app     varchar2(100 char),
    x_prime_region           varchar2(100 char),
    id_vl_source_application number,
    created_date             timestamp(6),
    expirydate               varchar2(100 byte),
    status                   number,
    timezone                 varchar2(150 byte)
);

alter table veranolink.vl_tokens
    add constraint vl_tokens_pk primary key ( id_vl_token )
        using index enable;


